  "code-review": { "sections": [{ "component": "hero", "props": { "badge": "PR #247", "title": "Authentication Service Refactor", "subtitle": "Replacing legacy JWT implementation with OAuth 2.0 + OpenID Connect for improved security and SSO support." } }, { "component": "code-block", "props": { "language": "typescript", "code": "// Before: Custom JWT implementation\nfunction createToken(userId: string): string {\n  const payload = { sub: userId, iat: Date.now() };\n  return base64Encode(JSON.stringify(payload)) + '.' +\n         base64Encode(sign(payload, SECRET));\n}\n\n// After: Using standard OAuth 2.0 client\nimport { OAuth2Client } from 'google-auth-library';\n\nconst authClient = new OAuth2Client(CLIENT_ID);\nasync function verifyToken(token: string) {\n  const ticket = await authClient.verifyIdToken({ idToken: token, audience: CLIENT_ID });\n  return ticket.getPayload();\n}", "filename": "src/auth/service.ts" } }, { "component": "callout", "props": { "type": "info", "icon": "ℹ️", "title": "Breaking Changes", "content": "This refactor deprecates the old /api/auth/login endpoint. New clients must use the /api/oauth/authorize flow." } }], "options": { "title": "Code Review: Auth Service", "theme": "dark" } },
